/bin/bash -c "python3 - <<'PY'
from pathlib import Path
import re
stats=[]
for p in [7,8,9]:
    for line in Path(f'tmp/pdfs/page-{p:02d}.txt').read_text().splitlines():
        pairs=re.findall(r'(\\d\\.\\d+)±(\\d\\.\\d+)',line)
        if not pairs:
            continue
        if p==9:
            assert len(pairs)==4,(p,pairs)
            stats.append((p,pairs[1][1],pairs[3][1]))
        else:
            assert len(pairs)%3==0,(p,pairs)
            for i in range(0,len(pairs),3):
                stats.append((p,pairs[i][1],pairs[i+2][1]))
print('Checked entries across Tables 2-6:',len(stats))
print('Matching reported raw_wiki and heuristic uncertainties:',sum(a==b for _,a,b in stats))
print('Nonzero matched pairs:',sum(a==b and float(a)>0 for _,a,b in stats))
PY"
